engine.onTick=t=>{$('timeDisplay').textContent=`${fmt(t)} / ${fmt(duration(p))}`;$('playhead').max=Math.max(.01,duration(p));$('playhead').value=String(t);$('playButton').textContent=engine.playing?'Ⅱ':'▶';updateTimelineCursor(t)};
const clone=()=>structuredClone(p);
function commit(label='Updated'){history.push(clone());if(history.length>60)history.shift();future=[];p.modifiedAt=Date.now();setStatus(label)}
let saving;
function setStatus(label='Saved'){p.modifiedAt=Date.now();$('saveStatus').textContent=label;$('statusLine').textContent=`${p.assets.length} sources · ${p.segments.length} video cuts · ${fmt(duration(p))}`;$('footerInfo').textContent=label;if(p.settings.autoSave&&!asrBusy){clearTimeout(saving);saving=setTimeout(()=>save(false),1000)}}
async function save(notify=true){try{const disk={...p,assets:p.assets.map(({url,file,...rest})=>rest)};await saveProject(disk);$('saveStatus').textContent='Saved locally';if(notify)toast('Project metadata saved to IndexedDB')}catch(e){toast(`Save failed: ${e.message}`,true)}}
function draw(){engine.setProject(p);$('previewHint').classList.toggle('hidden',p.segments.length>0);$('projectName').value=p.name;$('aspectSelect').value=p.settings.aspect;$('toggleCaptions').textContent=p.settings.captionOn?'CC On':'CC Off';$('timeDisplay').textContent=`${fmt(engine.time)} / ${fmt(duration(p))}`;$('playhead').max=Math.max(.01,duration(p));$('playhead').value=String(engine.time);renderAssets();renderTimeline();renderInspector();syncSourceRange();setStatus('Ready')}
